23:## Not done / known issues
24:
25:- Not tested end-to-end against the real API by the agents (they never read the token); the logic is unit-tested and the web build compiles. TODO(me): say what you checked by hand with your token.
26:- The pending-claims overlay is in memory only: after a reload within ~15s of a claim, Home can show the older snapshot until the next one.
27:- The persisted claim submission uses `localStorage`, so the resume-after-reload path works on web only (the target build).
28:- Activity is not refreshed when a claim settles (it refetches on open, pull-to-refresh or focus).
29:- `app.json` uses `web.output: "server"` (template default): the token gate may log a hydration warning on first load.
30:- No end-to-end or component tests; tests cover pure logic only. Light theme only.
import { atom } from 'jotai';

import type { PendingClaim } from '@/lib/pending-claims';

// Pure logic lives in lib (testable without jotai); re-exported so callers have one import.
export { applyPendingClaims, isNotInSnapshot, type PendingClaim } from '@/lib/pending-claims';

// shortcut: in-memory only, a reload loses the overlay until the next snapshot (<=15s); persist if that matters.
export const pendingClaimsAtom = atom<PendingClaim[]>([]);

/** Add (or replace, by claimId) after POST /v1/claims returns. */
export const addPendingClaimAtom = atom(null, (get, set, claim: PendingClaim) =>
  set(pendingClaimsAtom, [...get(pendingClaimsAtom).filter((c) => c.claimId !== claim.claimId), claim]),
);

/**
 * Drop when the claim FAILED (the server returns the amount to available).
 * Don't call it on completed: the last snapshot may predate the claim, and dropping
 * would show the amount as available again until the next snapshot; Home prunes it then.
 */
export const removePendingClaimAtom = atom(null, (get, set, claimId: string) =>
  set(pendingClaimsAtom, get(pendingClaimsAtom).filter((c) => c.claimId !== claimId)),
);

import { createStore } from 'jotai';

// Explicit store so non-React code (the React Query error handler) can read
// and clear the token.
export const appStore = createStore();
import { atom } from 'jotai';
import { atomWithStorage } from 'jotai/utils';

export const TOKEN_STORAGE_KEY = 'cashmine.token';

// Raw-string storage on top of localStorage (we ship a web build). Every access
// is guarded: private mode / disabled storage must not crash the app, it just
// means the token lives in memory for this session. On native there is no
// localStorage, so the same in-memory fallback applies.
// Same shape as jotai's (unexported) SyncStorage.
type TokenStorage = {
  getItem: (key: string, initialValue: string | null) => string | null;
  setItem: (key: string, value: string | null) => void;
  removeItem: (key: string) => void;
};

const memory = new Map<string, string>();

function getLocalStorage(): Storage | null {
  try {
    return typeof localStorage === 'undefined' ? null : localStorage;
  } catch {
    return null;
  }
}

const tokenStorage: TokenStorage = {
  getItem(key, initialValue) {
    try {
      const value = getLocalStorage()?.getItem(key);
      if (value) return value;
    } catch {
      // fall through to memory
    }
    return memory.get(key) ?? initialValue;
  },
  setItem(key, value) {
    if (!value) return this.removeItem(key);
    memory.set(key, value);
    try {
      getLocalStorage()?.setItem(key, value);
    } catch {
      // keep the in-memory copy only
    }
  },
  removeItem(key) {
    memory.delete(key);
    try {
      getLocalStorage()?.removeItem(key);
    } catch {
      // nothing else to clear
    }
  },
};

// null = no token yet. Read on init so the gate decides on the first render.
export const tokenAtom = atomWithStorage<string | null>(TOKEN_STORAGE_KEY, null, tokenStorage, {
  getOnInit: true,
});

/** Why the user was sent back to the token screen (e.g. a 401), if not by choice. */
export const signOutReasonAtom = atom<string | null>(null);
