        <Link href={{ pathname: '/claim/[asset]', params: { asset: persisted.body.asset } }} style={styles.link}>
          Go to {persisted.body.asset} claim
        </Link>
      </View>
    );
  }

  if (phase === 'submitting' || phase === 'unknown') {
    return (
      <View style={styles.center}>
        {header}
        {phase === 'submitting' ? (
